-- AI weekly wish cards (owner: Member 2) + the parents' child profile.
--
-- wish_decks: one generated deck per child per UTC week (cached; generated by
--   the server on the child's first open that week). Child reads own; writes
--   by the service role only.
-- wish_cards: new structured columns. Typed "Other" ideas are stored ONLY as
--   the cleaned label + tags (never the child's raw words).
-- child_profiles: parent-edited facts (birthday, grade, parent-noted
--   interests, dislikes, notes). Both parents read/write; children never.

-- ---------------------------------------------------------------------------
-- wish_decks
-- ---------------------------------------------------------------------------
create table public.wish_decks (
	id uuid primary key default gen_random_uuid(),
	family_id uuid not null references public.families (id) on delete cascade,
	child_id uuid not null references public.children (id) on delete cascade,
	week_start date not null,
	cards jsonb not null,
	source text not null check (source in ('ai', 'fallback')),
	created_at timestamptz not null default now(),
	unique (child_id, week_start)
);
create index wish_decks_family_id_idx on public.wish_decks (family_id);
create trigger wish_decks_set_family
	before insert or update of child_id on public.wish_decks
	for each row execute function public.set_family_id_from_child();

alter table public.wish_decks enable row level security;
create policy wish_decks_select_child on public.wish_decks
	for select to authenticated using (child_id = public.current_child_id());

-- ---------------------------------------------------------------------------
-- wish_cards: structured answers
-- ---------------------------------------------------------------------------
alter table public.wish_cards
	add column week_start date,
	add column card_kind text check (card_kind in ('activity', 'interest', 'gift')),
	add column option_key text check (char_length(option_key) <= 60),
	add column emoji text check (char_length(emoji) <= 16),
	add column tags text[] not null default '{}',
	add column is_custom boolean not null default false;
create index wish_cards_child_week_idx on public.wish_cards (child_id, week_start, card_kind);

-- The child may change this week's answers (the server deletes + re-inserts).
create policy wish_delete_child on public.wish_cards
	for delete to authenticated using (child_id = public.current_child_id());

-- ---------------------------------------------------------------------------
-- child_profiles
-- ---------------------------------------------------------------------------
create table public.child_profiles (
	child_id uuid primary key references public.children (id) on delete cascade,
	family_id uuid not null references public.families (id) on delete cascade,
	birthday date,
	grade text check (char_length(grade) <= 30),
	interests text[] not null default '{}' check (cardinality(interests) <= 12),
	dislikes text[] not null default '{}' check (cardinality(dislikes) <= 12),
	notes text check (char_length(notes) <= 600),
	updated_by uuid references public.members (id) on delete set null,
	updated_at timestamptz not null default now()
);
create index child_profiles_family_id_idx on public.child_profiles (family_id);
create trigger child_profiles_set_family
	before insert or update of child_id on public.child_profiles
	for each row execute function public.set_family_id_from_child();

alter table public.child_profiles enable row level security;
create policy child_profiles_select_parent on public.child_profiles
	for select to authenticated using (public.is_family_parent(family_id));
create policy child_profiles_insert_parent on public.child_profiles
	for insert to authenticated with check (public.is_family_parent(family_id));
create policy child_profiles_update_parent on public.child_profiles
	for update to authenticated
	using (public.is_family_parent(family_id)) with check (public.is_family_parent(family_id));

-- Both parents' "Lily's week" card updates live when the profile changes.
alter publication supabase_realtime add table public.child_profiles;
